def tf_part(tf, ratio, k1=1.2, b=0.75):
    return tf * (k1 + 1) / (tf + k1 * (1 - b + b * ratio))

print(round(tf_part(1, 2, b=0), 2), round(tf_part(1, 2), 2), round(tf_part(2, 2), 2))

def hybrid(bm25_scores, cos_scores, alpha=0.7):
    docs = set(bm25_scores) | set(cos_scores)
    fused = {d: alpha * cos_scores.get(d, 0) + (1 - alpha) * bm25_scores.get(d, 0) for d in docs}
    return sorted(fused, key=fused.get, reverse=True)

def mrr(runs):
    rrs = []
    for ranked, relevant in runs:
        ranks = [i for i, d in enumerate(ranked, start=1) if d in relevant]
        if not ranks:
            continue  # nothing relevant retrieved
        rrs.append(1 / ranks[0])
    return sum(rrs) / len(rrs)
